// ===== React Router v6 数据路由模式 =====
import {
  createBrowserRouter,
  RouterProvider,
  useLoaderData,
  useActionData,
  useNavigation,
  Form,
  redirect,
  Outlet,
  Link,
  useRouteError,
} from 'react-router-dom';

// 定义路由树（数据路由模式）
const router = createBrowserRouter([
  {
    path: '/',
    element: <RootLayout />,
    errorElement: <RootErrorBoundary />,
    children: [
      { index: true, element: <Home /> },
      {
        path: 'users/:userId',
        element: <UserDetail />,
        // loader 在路由匹配时并行执行，组件渲染前数据已就绪
        loader: async ({ params }) => {
          const res = await fetch(`/api/users/${params.userId}`);
          if (!res.ok) throw new Response('Not Found', { status: 404 });
          return res.json();
        },
        // action 处理表单提交，完成后自动重验证 loader
        action: async ({ params, request }) => {
          const formData = await request.formData();
          const res = await fetch(`/api/users/${params.userId}`, {
            method: 'PATCH',
            body: JSON.stringify({ name: formData.get('name') }),
            headers: { 'Content-Type': 'application/json' },
          });
          if (!res.ok) return { error: '更新失败' };
          return redirect(`/users/${params.userId}`);
        },
        errorElement: <UserErrorBoundary />,
      },
    ],
  },
  {
    path: '/login',
    loader: async ({ request }) => {
      const user = await getUser(request);
      if (user) throw redirect('/'); // 已登录则重定向
      return null;
    },
    element: <Login />,
  },
]);

function RootLayout() {
  const navigation = useNavigation();
  return (
    <div>
      <nav>
        <Link to="/">Home</Link>
      </nav>
      {/* 全局 Pending UI：导航 loading 时显示进度条 */}
      {navigation.state === 'loading' && <ProgressBar />}
      <Outlet />
    </div>
  );
}

function UserDetail() {
  const user = useLoaderData();  // loader 返回的数据
  const actionData = useActionData(); // action 返回的数据（如校验错误）
  return (
    <div>
      <h1>{user.name}</h1>
      <Form method="post">
        <input name="name" defaultValue={user.name} />
        <button type="submit">保存</button>
      </Form>
      {actionData?.error && <p style={{ color: 'red' }}>{actionData.error}</p>}
    </div>
  );
}

function UserErrorBoundary() {
  const error = useRouteError();
  if (error?.status === 404) return <p>用户不存在</p>;
  return <p>加载出错：{error.message}</p>;
}

// ===== Next.js 渲染策略 =====

// SSR：每次请求在服务端取数渲染
// app/users/[id]/page.tsx (App Router)
async function UserPage({ params }) {
  const user = await fetchUser(params.id); // 服务端直接取数，不需要 useEffect
  return <div>{user.name}</div>;
}

// SSG：构建时生成
// app/blog/[slug]/page.tsx
export async function generateStaticParams() {
  const posts = await fetchAllPosts();
  return posts.map((p) => ({ slug: p.slug }));
}

// ISR：定时重新生成
// next.config.js 或 route segment config
export const revalidate = 60; // 60秒后下一次请求触发重新生成
